using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Book of Vile Darkness (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class BookOfVileDarkness2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("book-of-vile-darkness", null, 0, MagicItemType.WondrousItem, ItemRarity.Artifact, true, ContentSource.RealmForge,
			null,
			("Libro delle fosche tenebre", "Oggetto meraviglioso, artefatto (richiede sintonia)",
			"Questo manoscritto di indicibile malvagità è il nutrimento di chi è schiavo del male: anche solo intravederne le pagine invita alla follia. Molti credono che l'abbia scritto il dio-lich Vecna, raccogliendovi ogni idea malata, ogni pensiero folle e ogni esempio della magia più nera; altri malvagi vi hanno poi aggiunto pagine e annotazioni, e in molti punti il testo originale è strappato o coperto di inchiostro, sangue e graffi. La natura non ne sopporta la presenza: le piante avvizziscono, gli animali si tengono lontani e perfino la pietra si sgretola se il libro vi resta appoggiato a lungo.\n\n***Sapienza immonda.*** Tra i suoi contenuti possono esserci un rituale per diventare un lich o un cavaliere della morte, i veri nomi di vari immondi e incantesimi di orrenda malvagità scelti dal GM.\n\nUna creatura in sintonia con il libro deve passare 80 ore a leggerlo e studiarlo per ottenerne i benefici; dopodiché può modificarne liberamente il contenuto, purché le modifiche servano il male. Quando una creatura non malvagia entra in sintonia con il libro, deve effettuare un tiro salvezza su Carisma con CD 17: se lo fallisce, il suo allineamento diventa neutrale malvagio.\n\nIl libro resta con il personaggio solo finché si impegna a diffondere il male: se non compie almeno un atto malvagio ogni 10 giorni, o se compie volontariamente un atto buono, il libro scompare. Se il personaggio muore mentre è in sintonia con esso, un'entità di grande malvagità ne reclama l'anima, e finché resta prigioniera non può essere riportato in vita in alcun modo.\n\n***Proprietà casuali.*** 3 proprietà benefiche minori, 1 proprietà benefica maggiore, 3 proprietà dannose minori e 2 proprietà dannose maggiori.\n\n***Caratteristiche alterate.*** Dopo lo studio, un punteggio di caratteristica a scelta del personaggio aumenta di 2 (fino a un massimo di 24) e un altro a sua scelta diminuisce di 2 (fino a un minimo di 3). Il libro non può alterare di nuovo i suoi punteggi.\n\n***Marchio delle tenebre.*** Dopo lo studio, il personaggio acquisisce una deformità fisica, segno della sua devozione alle tenebre: una runa malvagia sul volto, occhi neri e lucidi, corna sulla fronte o altro a scelta del GM. Il marchio gli concede vantaggio alle prove di Carisma (Persuasione) con le creature malvagie e di Carisma (Intimidire) con quelle non malvagie.\n\n***Comandare il male.*** Mentre è in sintonia con il libro e lo tiene in mano, il personaggio può usare un'azione per lanciare *dominare mostri* su un bersaglio malvagio (CD 18). Non può riusare questa proprietà fino all'alba successiva.\n\n***Sapere oscuro.*** Quando effettua una prova di Intelligenza per ricordare informazioni su un aspetto del male, come i demoni, il personaggio può consultare il libro e raddoppiare il suo bonus di competenza.\n\n***Linguaggio oscuro.*** Mentre porta il libro ed è in sintonia con esso, il personaggio può usare un'azione per recitarne delle parole nel Linguaggio Oscuro: ogni volta subisce 1d12 danni psichici, e ogni creatura non malvagia entro 4,5 metri da lui subisce 3d6 danni psichici.\n\n***Distruggere il libro.*** Le pagine strappate ritornano prima o poi nel libro. Se un solar lo strappa in due, il libro viene distrutto per 1d100 anni e poi si riforma in un angolo oscuro del multiverso. Una creatura in sintonia con esso per cento anni può scoprire una frase nascosta che, tradotta in Celestiale e pronunciata ad alta voce, distrugge sia chi parla sia il libro in un lampo di luce radiosa; ma finché il male esiste, il libro si riforma 1d10 × 100 anni dopo. Se il male scomparisse dal multiverso, il libro si ridurrebbe in polvere per sempre."),
			("Book of Vile Darkness", "Wondrous item, artifact (requires attunement)",
			"This manuscript of unspeakable wickedness is meat and drink to those in evil's thrall: even a glimpse of its pages invites madness. Many believe the lich-god Vecna wrote it, gathering every diseased idea, every deranged thought and every example of the blackest magic; other villains later added pages and notes, and in many places the original text is torn out or covered in ink, blood and scratches. Nature can't abide it: plants wither, animals keep away, and even stone crumbles if the book rests on it for long.\n\n***Vile Lore.*** Its contents might include a ritual to become a lich or a death knight, the true names of various fiends, and spells of horrific evil chosen by the DM.\n\nA creature attuned to the book must spend 80 hours reading and studying it to gain its benefits; afterwards it can freely change its contents, as long as the changes serve evil. When a non-evil creature attunes to the book, it must make a DC 17 Charisma saving throw: on a failure, its alignment becomes neutral evil.\n\nThe book stays with you only as long as you strive to spread evil: if you don't perform at least one evil act every 10 days, or if you willingly do good, the book disappears. If you die while attuned to it, an entity of great evil claims your soul, and you can't be brought back to life by any means while it remains imprisoned.\n\n***Random Properties.*** 3 minor beneficial properties, 1 major beneficial property, 3 minor detrimental properties and 2 major detrimental properties.\n\n***Adjusted Ability Scores.*** After the study, one ability score of your choice increases by 2 (to a maximum of 24) and another of your choice decreases by 2 (to a minimum of 3). The book can't adjust your scores again.\n\n***Mark of Darkness.*** After the study, you acquire a physical disfigurement, a sign of your devotion to darkness: an evil rune on your face, glossy black eyes, horns on your forehead or something else the DM chooses. The mark gives you advantage on Charisma (Persuasion) checks with evil creatures and Charisma (Intimidation) checks with non-evil ones.\n\n***Command Evil.*** While attuned to the book and holding it, you can use an action to cast *dominate monster* on an evil target (DC 18). You can't use this property again until the next dawn.\n\n***Dark Lore.*** When you make an Intelligence check to recall information about some aspect of evil, such as demons, you can consult the book and double your proficiency bonus.\n\n***Dark Speech.*** While you carry the book and are attuned to it, you can use an action to recite words from it in the foul Dark Speech: each time, you take 1d12 psychic damage, and each non-evil creature within 15 feet of you takes 3d6 psychic damage.\n\n***Destroying the Book.*** Torn pages eventually find their way back into the book. If a solar tears it in two, the book is destroyed for 1d100 years and then re-forms in a dark corner of the multiverse. A creature attuned to it for a hundred years can find a hidden phrase that, translated into Celestial and spoken aloud, destroys both the speaker and the book in a flash of radiance; but as long as evil exists, the book re-forms 1d10 × 100 years later. If evil vanished from the multiverse, the book would turn to dust forever.", null));
	}
}
